const chromiumPromise=import('@playwright/test');
(async()=>{const {chromium}=await chromiumPromise;const b=await chromium.launch();const p=await b.newPage();p.on('response',r=>{if(r.request().resourceType()==='font') console.log('FONT',r.status(),r.url())});p.on('requestfailed',r=>console.log('FAIL',r.url(),r.failure()));await p.goto('http://127.0.0.1:3310/en/fixture/detail?widget=supporting');console.log(await p.evaluate(async()=>{const a=[];for(const v of ['--font-manrope','--font-cormorant']){const f=getComputedStyle(document.documentElement).getPropertyValue(v).split(',')[0];try{const r=await document.fonts.load(`500 16px ${f}`,'Hello Цветы Cveće');a.push([v,f,r.map(x=>x.status)])}catch(e){a.push([v,f,String(e)])}}return a}));await b.close()})().catch(e=>{console.error(e);process.exitCode=1});
